// Jessie — Envoy Mirror v2 · Room Calendars
// One item per room resource calendar, read by `Read Room Calendar`.
// Studio E uses the LIVE id; the workflows' old c_18807te... is dead
// (docs/design/studio-e-id-fix.md, PENDING 43).
const ROOMS = {
  'Studio 1':'hitproductions.net_3737303833303637363538@resource.calendar.google.com',
  'Studio 2':'c_18871bprki2umhrkjc4qcaldse1f8@resource.calendar.google.com',
  'Studio 3':'c_1886me03bdcrki5bhu8vddknl472k@resource.calendar.google.com',
  'Studio 4':'c_188e94dapvbp8jvrjmuga6qbof826@resource.calendar.google.com',
  'Studio 5':'c_18889v3glj9cqiotg8j95jaqmdhmm@resource.calendar.google.com',
  'Studio 6':'c_18838qt2ru30ein7gcefjiarplkre@resource.calendar.google.com',
  'Studio 7':'c_188dupcj6cqfaipohqffj07ruq8de@resource.calendar.google.com',
  'Studio 8':'c_18863v8hd6f42isegdh9i30psuo9q@resource.calendar.google.com',
  'Studio A':'c_18843dclutqm6hl9nbeg002phapfu@resource.calendar.google.com',
  'Studio B':'c_1881vgb66tkpujjelnn3rniugd9pk@resource.calendar.google.com',
  'Studio C':'c_188797f37eu9ujs6ldpf3smn78joc@resource.calendar.google.com',
  'Studio D':'c_18801gc6ck77gho7jl0e1fug94u92@resource.calendar.google.com',
  'Studio E':'c_1888r4bbc2lhqgndmprism70nft64@resource.calendar.google.com',
  'Studio F':'c_188em7d58podeju3i8q6juqlufkls@resource.calendar.google.com',
  'Studio M':'c_1885k4adm87fqjd2j3j2usqftph5c@resource.calendar.google.com',
  'M1':'c_1889v46vd62fkjk3i7r1hsfem7tcm@resource.calendar.google.com',
  'M2':'c_1883ui6lnfc9ogt2hrmg57a30n72q@resource.calendar.google.com',
  'M3':'c_188d7dkqgnfs6hu4iunlu5ogftct0@resource.calendar.google.com',
  'M4':'c_18869nhmsj2uki8mljoi48v1cj7l4@resource.calendar.google.com',
  'M5':'c_1889h30ci9noqjcbnoogad9qk75vq@resource.calendar.google.com',
  'M6':'c_188f9gnq0a9tehf4g9ja57l83c0ts@resource.calendar.google.com',
  'M7':'c_1880r9hhk9c2agpbko87o7fojosh0@resource.calendar.google.com',
  'M8':'c_1884cu2cc84iujsjnu03s21f0ct9q@resource.calendar.google.com',
  'Salin':'c_1887hh5rsv6q4gt8hnu6ered170lg@resource.calendar.google.com',
  'Katha':'c_1881169pcpn12gsnm6i7sc0gjk7gk@resource.calendar.google.com',
  'Likha':'c_1886t6cjgrq0ihgpime01uibcqsg6@resource.calendar.google.com',
  'Lobby':'c_188227mpeagjuhi7gqlgns1di14be@resource.calendar.google.com'
};

// Same window for the room reads and the KDC read, so reconcile compares like
// with like. Real dates: QA's 2027 year-shifted bookings fall outside it.
const now = Date.now();
const timeMin = new Date(now - 24 * 3600 * 1000).toISOString();
const timeMax = new Date(now + 90 * 24 * 3600 * 1000).toISOString();

return Object.keys(ROOMS).map(room => ({ json: { room, calId: ROOMS[room], timeMin, timeMax } }));

// Jessie — Envoy Mirror v2 · Plan Changes
// Compares the Envoy bookings on the room calendars with the mirror copies on
// KDC Bookings and emits one item per write: create / update / delete, plus a
// leading `summary` item that is never written (it is the run's record).
//
// Fails CLOSED, the two ways v1 did not:
//  - a room whose read errored, or came back incomplete, gets no deletes this
//    run (v1 read a failed room as "every booking cancelled" and deleted them);
//  - a KDC read that is incomplete throws, so nothing is written (v1 read a
//    failed KDC list as "no copies yet" and duplicated everything).
//    A KDC read that errors stops the workflow before this node.
// And fails LOUDLY when no room calendar could be read at all (an expired or
// revoked Google credential): the run goes red instead of green-and-idle.
const KDC = 'c_re5mcrg9om0macp9doqhlsi83g@group.calendar.google.com';
const DELETE_CAP = 25;   // more deletes than this in one run: hold them all, report

const reads = $('Merge Reads').all().map(i => i.json);
const rooms = $('Room Calendars').all().map(i => i.json);
const kdc = $input.first().json;

if (kdc.error) throw new Error('KDC Bookings read failed; nothing written: ' + JSON.stringify(kdc.error).slice(0, 300));
if (!Array.isArray(kdc.items)) throw new Error('KDC Bookings read returned no items array; nothing written.');
if (kdc.nextPageToken) throw new Error('KDC Bookings read was incomplete (more than one page); nothing written.');

const isoOf = (x) => (x && (x.dateTime || x.date)) || '';
const sameTime = (a, b) => {
  if (!a || !b) return false;
  if (a.dateTime && b.dateTime) return Date.parse(a.dateTime) === Date.parse(b.dateTime);
  return isoOf(a) === isoOf(b);
};

// Narrow scope: Envoy-origin only. Jessie's own bookings sit on a room calendar
// organized by KDC Bookings, so they are excluded first; personal-calendar
// bookings are organized by a person and carry no Envoy marker.
const isEnvoy = (ev, calId) => {
  const org = String((ev.organizer || {}).email || '').toLowerCase();
  if (org === KDC) return false;
  return /created by envoy/i.test(String(ev.description || ''))
      || /^rooms/.test(String(ev.id || ''))
      || org === String(calId).toLowerCase();
};

// Pairing by position is only safe when every room produced exactly one read.
const paired = reads.length === rooms.length;

const desired = {};        // sourceKey -> { room, calId, summary, start, end }
const unreadable = [], incomplete = [];
const readOk = {};         // calId -> true when that room's list is complete
reads.forEach((r, idx) => {
  const room = r.room || (rooms[idx] || {}).room || '?';
  const calId = r.calId || (rooms[idx] || {}).calId || '';
  if (!paired || r.error || !Array.isArray(r.items)) { unreadable.push(room); return; }
  if (r.nextPageToken) incomplete.push(room); else readOk[calId] = true;
  for (const ev of r.items) {
    if (!ev || ev.status === 'cancelled' || !ev.start || !ev.end) continue;
    if (!isEnvoy(ev, calId)) continue;
    // Location: the tablet booking's own, which is the room resource's full name
    // ("KDC Plaza-Top Level-Studio 7 (7)"), the same string Google puts on Jessie's
    // bookings. Move Booking's Check New Window compares locations EXACTLY, so a
    // bare "Studio 7" would not clash with a Jessie booking being moved onto it.
    const srcLoc = String(ev.location || '').trim();
    const location = srcLoc && srcLoc.toLowerCase().indexOf(room.toLowerCase()) !== -1 ? srcLoc : room;
    desired[calId + ':' + ev.id] = { room, calId, location,
      summary: String(ev.summary || '').trim() || 'Tablet booking', start: ev.start, end: ev.end };
  }
});

if (!paired)
  throw new Error('Room reads did not pair with rooms (' + reads.length + ' reads, ' + rooms.length
    + ' rooms); Merge Reads is misbehaving. Nothing written.');
if (rooms.length && unreadable.length === rooms.length)
  throw new Error('No room calendar could be read (' + rooms.length + ' of ' + rooms.length
    + '); check the Google Calendar credential. Nothing written.');

const existing = {};       // sourceKey -> { id, summary, location, start, end }
let strays = 0;            // mirror copies with no source key; left alone
for (const ev of kdc.items) {
  if (!ev || ev.status === 'cancelled') continue;
  const p = (ev.extendedProperties && ev.extendedProperties.private) || {};
  if (!p.envoyMirrorSource) { strays++; continue; }
  if (existing[p.envoyMirrorSource]) {   // a duplicate copy: keep the first, remove the rest
    existing[p.envoyMirrorSource + '#dup#' + ev.id] = { id: ev.id, dup: true, source: p.envoyMirrorSource };
    continue;
  }
  existing[p.envoyMirrorSource] = { id: ev.id, summary: ev.summary || '',
    location: ev.location || '', start: ev.start, end: ev.end };
}

const titleOf = (d) => d.room + ' - ' + d.summary;
const bodyFor = (d, sourceKey) => ({
  summary: titleOf(d),
  location: d.location,
  description: 'Created by Envoy (mirrored). Manage this booking in Envoy.\nsource: ' + sourceKey,
  start: d.start,
  end: d.end,
  transparency: 'opaque',
  reminders: { useDefault: false },
  extendedProperties: { private: { envoyMirror: '1', envoyMirrorSource: sourceKey } }
});
const evUrl = 'https://www.googleapis.com/calendar/v3/calendars/' + encodeURIComponent(KDC) + '/events';

const creates = [], updates = [], deletes = [];
for (const sk of Object.keys(desired)) {
  const d = desired[sk], ex = existing[sk];
  if (!ex) creates.push({ op: 'create', url: evUrl, room: d.room, sourceKey: sk, body: bodyFor(d, sk) });
  else if (ex.summary !== titleOf(d) || ex.location !== d.location
        || !sameTime(ex.start, d.start) || !sameTime(ex.end, d.end))
    updates.push({ op: 'update', url: evUrl + '/' + encodeURIComponent(ex.id), eventId: ex.id,
      room: d.room, sourceKey: sk, body: bodyFor(d, sk) });
}
let skippedDeletes = 0;
for (const key of Object.keys(existing)) {
  const ex = existing[key];
  const sk = ex.dup ? ex.source : key;
  if (!ex.dup && desired[sk]) continue;
  const calId = sk.slice(0, sk.indexOf(':'));   // calendar ids and event ids carry no ':'
  // No delete unless the source room was read completely this run. A source
  // key naming a room no longer in the list is left for a human.
  if (!ex.dup && !readOk[calId]) { skippedDeletes++; continue; }
  deletes.push({ op: 'delete', url: evUrl + '/' + encodeURIComponent(ex.id), eventId: ex.id, sourceKey: sk,
    duplicate: !!ex.dup });
}
const deletesHeld = deletes.length > DELETE_CAP;

const summary = {
  op: 'summary', ran: new Date().toISOString(), rooms: rooms.length, paired,
  unreadable, incomplete, desired: Object.keys(desired).length,
  existing: Object.keys(existing).length, strays,
  creates: creates.length, updates: updates.length,
  deletes: deletesHeld ? 0 : deletes.length, deletesHeld: deletesHeld ? deletes.length : 0,
  skippedDeletes
};

return [summary, ...creates, ...updates, ...(deletesHeld ? [] : deletes)].map(json => ({ json }));
